SELECT e.symbol, e.observed_at, e.created_at, TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at)/1000 AS lag_ms FROM crypto_ai.market_price_event e WHERE e.observed_at BETWEEN '2026-10-12 09:56:50' AND '2026-10-12 10:05:21' AND TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at) > 1000000 ORDER BY e.observed_at LIMIT 60;
SELECT DATE_FORMAT(e.observed_at, '%Y-%m-%d %H:%i') AS minute_ksa, COUNT(*) AS n_gt1s, COUNT(DISTINCT e.symbol) AS symbols, MAX(TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at))/1000 AS max_lag_ms FROM crypto_ai.market_price_event e WHERE e.observed_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 10:30:00' AND TIMESTAMPDIFF(MICROSECOND, e.observed_at, e.created_at) > 1000000 GROUP BY minute_ksa ORDER BY max_lag_ms DESC LIMIT 40;
SELECT w.id, w.symbol, w.side, w.executed_at, s.completed_at FROM crypto_ai.wallet_trade w LEFT JOIN crypto_ai.signal_processing_work s ON s.signal_id = w.signal_id WHERE w.executed_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 10:30:00' ORDER BY w.executed_at LIMIT 200;